int main(void){struct environment e;CHECK(open(&e,detailed,reference,1)==0&&built(&e)==0);e.old=e.input;e.input=NULL;uint64_t hash=owners_hash(e.old);CHECK(hash);const char* source="UBE SOURCE 1 MODULE\nAttribute UBE_Name = \"A\"\nType Token As Byte\nEnd Type\nIntrinsic Function MakeToken(ByVal x As Byte) As Token\nAttribute A.[MakeToken].[UBE_Primitive] = \"Value.Pack\"\nEnd Function\nSub Main()\nEnd Sub\n";CHECK(put(&e.first,source)==0);(void)ube_gc_collect();size_t baseline=ube_gc_live_allocation_bytes();CHECK(remake(&e,1,0)==0);struct failure f={.kind=5,.code=1428};source_observation(e.input);begin(0);int ok=catalog_build(e.input,&f);end();CHECK(ok&&f.kind==0&&decl(e.input,2)->auxiliary==1);size_t sites=observed.allocations,need=observed.roots_peak-observed.roots_before;CHECK(sites>0&&sites<4096&&need<=512);e.input=NULL;(void)ube_gc_collect();CHECK(ube_gc_live_allocation_bytes()==baseline);for(size_t site=1;site<=sites;++site){CHECK(remake(&e,1,0)==0);f=(struct failure){.kind=5,.code=1428};source_observation(e.input);begin(site);ok=catalog_build(e.input,&f);end();if(ok||f.kind!=5||f.code!=1428)fprintf(stderr,"primitive fault site=%zu ok=%d failure=%d:%d\n",site,ok,f.kind,f.code);CHECK(!ok&&f.kind==5&&f.code==1428&&owners_hash(e.old)==hash);e.input=NULL;(void)ube_gc_collect();CHECK(ube_gc_live_allocation_bytes()==baseline);}CHECK(remake(&e,1,0)==0&&built(&e)==0&&decl(e.input,2)->auxiliary==1&&owners_hash(e.old)==hash);CHECK(close_env(&e)==0);printf("PASS catalog primitive fault assertions:%u actualAllocationSites:%zu rootNeed:%zu\n",assertions,sites,need);return 0;}
